import sys
lines = sys.stdin.read().splitlines()
board = []
for line in lines:
    row = [c for c in line.split() if c]
    if len(row) == 9: board.append(row)
def is_valid(r, c, ch):
    for i in range(9):
        if board[r][i] == ch or board[i][c] == ch: return False
        if board[3*(r//3) + i//3][3*(c//3) + i%3] == ch: return False
    return True
def solve():
    for r in range(9):
        for c in range(9):
            if board[r][c] == '.':
                for ch in '123456789':
                    if is_valid(r, c, ch):
                        board[r][c] = ch
                        if solve(): return True
                        board[r][c] = '.'
                return False
    return True
solve()
for r in board:
    print(' '.join(r))
